/**
 * @file forward_main.cpp
 * @brief Forward Service 守护进程主程序入口。
 */

#include "forward_service.h"
#include <csignal>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <unistd.h>

/** @brief 守护进程运行控制原子标志 */
static volatile sig_atomic_t g_keep_running = 1;

/**
 * @brief 信号处理回调，捕获 SIGINT/SIGTERM 后安全退出事件循环
 * @param sig 信号值
 */
static void signal_handler(int sig) {
    (void)sig;
    g_keep_running = 0;
}

/**
 * @brief 解析命令行参数并填充 Forward 服务启动配置
 * @param argc 参数数量
 * @param argv 参数数组
 * @param cfg 配置结构体指针
 */
static void parse_args(int argc, char** argv, forward_service_config_t* cfg) {
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--port") == 0 && (i + 1 < argc)) {
            cfg->serial_port = argv[++i];
        } else if (strcmp(argv[i], "--firmware-dir") == 0 && (i + 1 < argc)) {
            cfg->firmware_dir = argv[++i];
        } else if (strcmp(argv[i], "--baud") == 0 && (i + 1 < argc)) {
            cfg->baud_rate = (uint32_t)strtoul(argv[++i], nullptr, 10);
        } else if (strcmp(argv[i], "--dbus-custom") == 0 && (i + 1 < argc)) {
            cfg->dbus_bus_type = AISOC_DBUS_BUS_CUSTOM;
            cfg->dbus_custom_address = argv[++i];
        } else if (strcmp(argv[i], "--dds-domain") == 0 && (i + 1 < argc)) {
            cfg->dds_domain_id = (uint32_t)strtoul(argv[++i], nullptr, 10);
        } else if (strcmp(argv[i], "--allow-offline-start") == 0) {
            cfg->allow_offline_start = true;
        }
    }
}

/**
 * @brief 处理启动节点探测结果；仅在显式 --allow-offline-start 时降级存活，默认保持 fail-fast。
 * @param state Forward 服务运行时状态指针
 * @param cfg 服务启动配置只读指针
 * @param probe_st 启动探测返回值
 * @return 0 表示可继续进入事件循环，非 0 表示应终止进程并返回该退出码
 */
static int handle_startup_probe(
    forward_service_state_t* state,
    const forward_service_config_t* cfg,
    aisoc_fwd_status_t probe_st
) {
    if (probe_st == AISOC_FWD_OK) {
        return 0;
    }
    if (!cfg->allow_offline_start) {
        std::fprintf(stderr, "[FWD START] stage=NODE_PROBE error_code=%d\n", probe_st);
        return 3;
    }
    // 生产自启降级模式：仅向首探失败节点发射离线信号，保留串口与在线节点自愈能力。
    if (!state->cached_mc_ver_valid) {
        forward_service_emit_link_state(state, 1U, false, "STARTUP_PROBE_FAILED");
    }
    if (!state->cached_th_ver_valid) {
        forward_service_emit_link_state(state, 2U, false, "STARTUP_PROBE_FAILED");
    }
    std::fprintf(stderr, "[FWD START] stage=NODE_PROBE mode=OFFLINE_DEGRADED error_code=%d\n",
                 probe_st);
    std::fflush(stderr);
    return 0;
}

/**
 * @brief Forward Service 守护进程主函数
 * @param argc 参数数量
 * @param argv 参数数组
 * @return 0 表示正常退出，非 0 表示启动失败
 */
int main(int argc, char** argv) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    forward_service_config_t cfg = {};
    cfg.serial_port = AISOC_FWD_DEFAULT_PORT;
    cfg.baud_rate = AISOC_FWD_DEFAULT_BAUD;
    cfg.dbus_bus_type = AISOC_DBUS_BUS_SESSION;
    parse_args(argc, argv, &cfg);

    forward_service_state_t state;
    aisoc_fwd_status_t st = forward_service_init(&cfg, &state);
    if (st != AISOC_FWD_OK) {
        return 1;
    }

    st = forward_service_start(&state);
    if (st != AISOC_FWD_OK) {
        forward_service_stop(&state);
        return 2;
    }

    // 默认启动保持 fail-fast 退出码 3；仅传入 --allow-offline-start 时允许断连降级存活。
    st = forward_service_probe_versions(&state, 200U);
    const int probe_rc = handle_startup_probe(&state, &cfg, st);
    if (probe_rc != 0) {
        forward_service_stop(&state);
        return probe_rc;
    }
    std::printf("[FORWARD] Service active on %s at %u baud (DDS domain %u)\n",
                cfg.serial_port, cfg.baud_rate, cfg.dds_domain_id);
    std::fflush(stdout);

    while (g_keep_running && state.running) {
        bool dispatched = false;
        forward_service_dispatch(&state, 100, &dispatched);
    }

    std::printf("[FORWARD] Shutting down service...\n");
    std::fflush(stdout);
    forward_service_stop(&state);
    return 0;
}
