def verify_mc_timeout_recovery(ctx):
    """验证 MC 超时冷启后挂断 PTY1、原子切换 PTY2，由 DM 500ms 轮询自动重开串口并恢复在线。"""
    sig_log = ctx['sig_log']
    if not wait_until(lambda: has_link_signal(sig_log, 1, False, 'STARTUP_PROBE_FAILED'), 1.5):
        return False
    start_device_manager(ctx)
    # 停止旧模型线程后再关闭 master1 制造挂断，避免模型读已关闭 fd 并防止清理阶段重复 close。
    stop_model(ctx['model'])
    close_pty_pair(ctx['open_fds'], ctx['pty1'])
    hangup_at = time.monotonic()
    port_closed = wait_until(
        lambda: (
            time.monotonic() - hangup_at >= 0.55
            and query_port_open(ctx) is False
            and is_node_offline(query_dm_devices(ctx).get('mc'))
        ),
        3.0,
    )
    if not port_closed:
        return False
    (_, slave2), model2 = open_pty_model(ctx['open_fds'], '')
    ctx['models'].append(model2)
    atomic_switch_symlink(ctx['uart_link'], os.ttyname(slave2))
    # 严禁手动调用 QueryVersion：仅只读轮询 GetPortStatus/GetVersionInfo 验证 DM 500ms 自动恢复。
    return wait_until(lambda: _mc_recovered_ok(ctx), 4.0)


def _mc_recovered_ok(ctx):
    """检查串口已重开、DM 版本矩阵双端在线且 dbus_signals.log 捕获到恢复信号。"""
    if query_port_open(ctx) is not True:
        return False
    devs = query_dm_devices(ctx)
    if not (is_node_online(devs.get('mc')) and is_node_online(devs.get('th'))):
        return False
    return has_link_signal(ctx['sig_log'], 1, True, 'OK') and has_link_signal(ctx['sig_log'], 2, True, 'OK')


def verify_th_timeout_recovery(ctx):
    """验证 TH 半断连冷启后 DM 自动识别 MC 在线/TH 离线，清零故障后纯等待 DM 500ms 自愈。"""
    sig_log, model = ctx['sig_log'], ctx['model']
    if not wait_until(lambda: has_link_signal(sig_log, 2, False, 'STARTUP_PROBE_FAILED'), 1.5):
        return False
    start_device_manager(ctx)
    half_degraded = wait_until(
        lambda: (
            list(model.commands).count((3, 1)) >= 2
            and is_node_online(query_dm_devices(ctx).get('mc'))
            and is_node_offline(query_dm_devices(ctx).get('th'))
        ),
        4.0,
    )
    if not half_degraded:
        return False
    # 恢复 TH 响应后严禁手动调用 QueryVersion，纯等待 DM 500ms 轮询自动刷新在线。
    model.fault = ''
    return wait_until(
        lambda: (
            is_node_online(query_dm_devices(ctx).get('mc'))
            and is_node_online(query_dm_devices(ctx).get('th'))
            and has_link_signal(sig_log, 2, True, 'OK')
        ),
        4.0,
    )


def evaluate_scenario(ctx):
    """根据场景分支核验进程退出码、D-Bus 响应、日志标记与自愈闭环。"""
    scenario, daemon, log = ctx['scenario'], ctx['daemon'], ctx['log']
    deps, addr, env, model = ctx['deps'], ctx['address'], ctx['env'], ctx['model']
    if scenario == 'normal':
        res = dbus_call(deps, addr, env, ['org.aisoc.ForwardInterface.QueryVersion', 'byte:1', 'uint32:500'])
        return daemon.poll() is None and res.returncode == 0 and 'int32 0' in res.stdout and model.commands == [(2, 1), (3, 1), (2, 1)]
    if scenario == 'mc_boot':
        return daemon.poll() is None and 'mode=MC_BOOT_RECOVERY' in log and verify_mc_boot_readonly_and_recover(ctx)
    if scenario == 'offline_allow_mc_timeout':
        return daemon.poll() is None and 'mode=OFFLINE_DEGRADED' in log and verify_mc_timeout_recovery(ctx)
    if scenario == 'offline_allow_th_timeout':
        return daemon.poll() is None and 'mode=OFFLINE_DEGRADED' in log and verify_th_timeout_recovery(ctx)
    if daemon.poll() is None:
        try:
            daemon.wait(timeout=0.5)
        except subprocess.TimeoutExpired:
            pass
    exp_code = 2 if scenario in ('open_failure', 'offline_allow_open_failure') else 3
    return daemon.poll() == exp_code and 'Service active' not in log


