def parse_port_status(stdout):
    """从 ForwardInterface.GetPortStatus 应答中解析串口是否打开。"""
    for line in stdout.splitlines():
        stripped = line.strip()
        if stripped == 'boolean true':
            return True
        if stripped == 'boolean false':
            return False
    return None


def parse_version_info(stdout):
    """从 DeviceInterface.GetVersionInfo 应答中解析版本矩阵 JSON 字典。"""
    for line in stdout.splitlines():
        stripped = line.strip()
        if stripped.startswith('string "') and stripped.endswith('"'):
            try:
                return json.loads(stripped[len('string "'):-1])
            except json.JSONDecodeError:
                return None
    return None


def parse_link_signals(log_path):
    """从 dbus_signals.log 解析完整的 LinkStateChanged(node, connected, reason) 信号列表。"""
    if not log_path.exists():
        return []
    lines = log_path.read_text(errors='replace').splitlines()
    signals, idx = [], 0
    while idx + 3 < len(lines):
        if 'interface=org.aisoc.ForwardInterface; member=LinkStateChanged' not in lines[idx]:
            idx += 1
            continue
        b_line, bool_line, str_line = lines[idx + 1].strip(), lines[idx + 2].strip(), lines[idx + 3].strip()
        if b_line.startswith('byte ') and bool_line.startswith('boolean ') and str_line.startswith('string "'):
            signals.append((int(b_line[5:]), bool_line == 'boolean true', str_line[8:-1]))
            idx += 4
        else:
            idx += 1
    return signals


def has_link_signal(log_path, node, connected, reason):
    """检查 dbus_signals.log 是否捕获到指定节点、状态与原因的 LinkStateChanged 信号。"""
    return (node, connected, reason) in parse_link_signals(log_path)


