class StartupModel(DeviceModel):
    """可控设备模型：支持按节点注入静默超时，以及在线切换 Boot/App 与应答 0x1C。"""

    def respond(self, node, cmd, sequence, data):
        """按节点故障标记决定静默或回复 0x01 版本 / 0x1C 控制台回执。"""
        if cmd == 1:
            assert data == b''
            silent = self.fault == 'mc_timeout' and node == 2
            silent = silent or (self.fault == 'th_timeout' and node == 3)
            if silent:
                self.commands.append((node, cmd))
                return
            super().respond(node, cmd, sequence, data)
            return
        if cmd == 0x1C:
            self.commands.append((node, cmd))
            payload = struct.pack('<BBH', 0, 4, sequence)
            os.write(self.fd, frame(node, 0x1C, sequence, payload))
            return
        raise AssertionError(f'unexpected cmd {cmd}')


def _run_dbus_send(cmd, env):
