    return subprocess.run(cmd, env=env, capture_output=True, text=True, timeout=2)


def dbus_call(dependencies, address, env, args):
    """通过 dbus-send 向 org.aisoc.Forward 发送单次方法调用并返回 CompletedProcess。"""
    cmd = [
        str(dependencies / 'bin/dbus-send'),
        '--bus=' + address,
        '--dest=org.aisoc.Forward',
        '--type=method_call',
        '--print-reply',
        '--reply-timeout=1000',
        '/org/aisoc/forward',
    ] + args
    return _run_dbus_send(cmd, env)


def dbus_device_call(dependencies, address, env, method):
    """通过 dbus-send 向 org.aisoc.Device 发送只读方法调用并返回 CompletedProcess。"""
    cmd = [
        str(dependencies / 'bin/dbus-send'),
        '--bus=' + address,
        '--dest=org.aisoc.Device',
        '--type=method_call',
        '--print-reply',
        '--reply-timeout=1000',
        '/org/aisoc/device',
        'org.aisoc.DeviceInterface.' + method,
    ]
    return _run_dbus_send(cmd, env)


